# Start-DshSandbox.ps1 -- host-side thin CLI over SandboxLifecycle.psm1.
#
# Usage (host):
#   powershell -NoProfile -File scripts/dsh-sidecar/sandbox/Start-DshSandbox.ps1 `
#     -Mode Build -ConfigPath <runDir>\build.wsb [-FinishTimeoutSec 3600] [-CloseGraceSec 30]
#
# Contract (DEV DOC v6 SS4.3):
#   - Start is the only host entry that launches this run's sandbox. It validates the existing
#     config (generated by New-DshSandboxConfig.ps1; Start never rewrites it) and then calls
#     SandboxLifecycle.psm1's Invoke-SandboxLifecycle with RealSandboxProcessAdapter.ps1.
#   - Start itself never calls a package manager, a JavaScript runtime, the runtime binary,
#     the probe script, backup or restore. All of that happens inside the sandboxed entry
#     script after LogonCommand.
#   - Exit codes are the lifecycle module's: 0 destroyed after success; 1 script failed or
#     timed out (destroyed when possible); 2 config/hash/identity/destroy/validator failure.

param(
  [Parameter(Mandatory = $true)][ValidateSet('Build', 'Probe')][string]$Mode,
  [Parameter(Mandatory = $true)][string]$ConfigPath,
  [int]$FinishTimeoutSec = 3600,
  [int]$CloseGraceSec = 30
)

$ErrorActionPreference = 'Stop'

function Fail([string]$code, [string]$message, [int]$exitCode = 2) {
  Write-Output ([ordered]@{ ok = $false; code = $code; message = $message } | ConvertTo-Json -Compress -Depth 6)
  exit $exitCode
}

$modeLower = $Mode.ToLower()
$configFull = [System.IO.Path]::GetFullPath($ConfigPath)
$runDir = Split-Path -Parent $configFull
$expectedName = "$modeLower.wsb"
if ((Split-Path -Leaf $configFull) -ne $expectedName) { Fail 'CONFIG_NAME' "config must be named $expectedName in the run dir" 2 }
$incoming = Join-Path $runDir 'incoming'
$outgoing = Join-Path $runDir 'outgoing'
$orchestrationPath = Join-Path $runDir 'orchestration.json'
foreach ($path in @($configFull, $orchestrationPath)) {
  if (-not (Test-Path -LiteralPath $path)) { Fail 'RUN_ARTIFACT_MISSING' "missing required file: $path" 2 }
}
foreach ($path in @($incoming, $outgoing)) {
  if (-not (Test-Path -LiteralPath $path)) { Fail 'RUN_DIR_MISSING' "missing run directory: $path" 2 }
}

# -- re-validate the frozen config posture (Start must not rewrite it) --------
$configText = Get-Content -LiteralPath $configFull -Raw -Encoding UTF8
if ($configText.IndexOf('%USERPROFILE%', [System.StringComparison]::OrdinalIgnoreCase) -ge 0) {
  Fail 'CONFIG_HOST_PATH_LEAK' 'config must not contain the %USERPROFILE% placeholder' 2
}
$xml = [xml]$configText
if (@($xml.Configuration.MappedFolders.MappedFolder).Count -ne 2) { Fail 'CONFIG_MAPPING_COUNT' 'config must have exactly two MappedFolders' 2 }
$maps = @($xml.Configuration.MappedFolders.MappedFolder)
$incomingMap = $maps | Where-Object { [string]$_.SandboxFolder -eq 'C:\SynovaLab\incoming' }
$outgoingMap = $maps | Where-Object { [string]$_.SandboxFolder -eq 'C:\SynovaLab\outgoing' }
if ($null -eq $incomingMap -or $null -eq $outgoingMap) { Fail 'CONFIG_MAPPING_TARGET' 'mappings must target C:\SynovaLab\incoming and C:\SynovaLab\outgoing' 2 }
if ([string]$incomingMap.ReadOnly -ne 'true') { Fail 'CONFIG_MAPPING_READONLY' 'incoming mapping must be ReadOnly=true' 2 }
if ([string]$outgoingMap.ReadOnly -ne 'false') { Fail 'CONFIG_MAPPING_READONLY' 'outgoing mapping must be ReadOnly=false' 2 }
if ([System.IO.Path]::GetFullPath([string]$incomingMap.HostFolder) -ne [System.IO.Path]::GetFullPath($incoming)) { Fail 'CONFIG_HOST_FOLDER' 'incoming HostFolder must be the run dir incoming' 2 }
if ([System.IO.Path]::GetFullPath([string]$outgoingMap.HostFolder) -ne [System.IO.Path]::GetFullPath($outgoing)) { Fail 'CONFIG_HOST_FOLDER' 'outgoing HostFolder must be the run dir outgoing' 2 }

$expectedNetworking = if ($modeLower -eq 'build') { 'Enable' } else { 'Disable' }
if ([string]$xml.Configuration.Networking -ne $expectedNetworking) { Fail 'CONFIG_NETWORKING' "config Networking must be $expectedNetworking for $Mode" 2 }
foreach ($node in @('ClipboardRedirection', 'AudioInput', 'VideoInput', 'PrinterRedirection', 'vGPU')) {
  if ([string]$xml.Configuration.$node -ne 'Disable') { Fail 'CONFIG_SECURITY' "$node must be Disable" 2 }
}
if ([string]$xml.Configuration.ProtectedClient -ne 'Enable') { Fail 'CONFIG_SECURITY' 'ProtectedClient must be Enable' 2 }

$modulePath = Join-Path $PSScriptRoot 'SandboxLifecycle.psm1'
$adapterPath = Join-Path $PSScriptRoot 'RealSandboxProcessAdapter.ps1'
if (-not (Test-Path -LiteralPath $modulePath)) { Fail 'MODULE_MISSING' "missing $modulePath" 2 }
if (-not (Test-Path -LiteralPath $adapterPath)) { Fail 'ADAPTER_MISSING' "missing $adapterPath" 2 }

Import-Module -Name $modulePath -Force
$exitCode = Invoke-SandboxLifecycle -Mode $Mode -ConfigPath $configFull -OrchestrationPath $orchestrationPath `
  -IncomingDir $incoming -OutgoingDir $outgoing -AdapterPath $adapterPath `
  -FinishTimeoutSec $FinishTimeoutSec -CloseGraceSec $CloseGraceSec
exit $exitCode
